TypeScript example:

// simplified pseudo-example
import { createMultiplexStream } from '@redwood/inference-sdk';
const stream = await createMultiplexStream({ model: 'rw-13b' });
for await (const frame of stream) {
  switch (frame.kind) {
    case 'model_delta':
      stdout.write(frame.payload.text);
      break;
    case 'tool_call':
      // call local tool, then send tool_result event back
      const result = await myTool.invoke(frame.payload);
      stream.send({ id: frame.id, kind: 'tool_result', payload: { result } });
      break;
    case 'structured_fragment':
      // fragments are JSON strings that assemble into a final object by seq
      assembler.push(frame.id, frame.seq, JSON.parse(frame.payload));
      break;
    case 'meta':
      console.debug('meta event', frame.payload);
      break;
  }
}

Go example:

// simplified pseudo-example
stream, err := sdk.CreateMultiplexStream(ctx, &sdk.StreamOptions{Model: "rw-13b"})
if err != nil { return err }
for frame := range stream.Frames() {
  switch frame.Kind {
  case sdk.KindModelDelta:
    os.Stdout.Write([]byte(frame.Payload.Text))
  case sdk.KindToolCall:
    go func(f sdk.Frame) {
      res := myTool.Invoke(f.Payload)
      stream.Send(sdk.Frame{ID: f.ID, Kind: sdk.KindToolResult, Payload: res})
    }(frame)
  case sdk.KindStructuredFragment:
    assembler.Push(frame.ID, frame.Seq, frame.Payload)
  default:
    log.Debugf("meta %v", frame.Payload)
  }
}
